import os
import json
from typing import Any, Dict, List, Optional, Union

import boto3
from botocore.exceptions import BotoCoreError, ClientError


def query_cloudwatch_metrics(
    namespace: str,
    metric_name: str,
    dimensions: Optional[Dict[str, str]] = None,
    start_time: Optional[Union[str, Any]] = None,
    end_time: Optional[Union[str, Any]] = None,
    period: int = 300,
    statistics: Optional[List[str]] = None,
    unit: Optional[str] = None,
    max_datapoints: int = 1000,
    scan_by: str = "TimestampDescending",
) -> List[Dict[str, Any]]:
    """
    Query Amazon CloudWatch metric data filtered by resource labels/dimensions.

    Args:
        namespace: CloudWatch metric namespace (e.g., "AWS/EC2").
        metric_name: Metric name (e.g., "CPUUtilization").
        dimensions: Mapping of dimension names to values used as filters.
        start_time: Start time (datetime preferred; ISO8601 string accepted if parseable by boto3/botocore).
        end_time: End time (datetime preferred; ISO8601 string accepted if parseable by boto3/botocore).
        period: Aggregation period in seconds.
        statistics: CloudWatch statistics such as ["Average", "Minimum", "Maximum"].
        unit: Optional CloudWatch unit filter.
        max_datapoints: Maximum datapoints returned.
        scan_by: Sort direction, typically "TimestampDescending" or "TimestampAscending".

    Returns:
        A list of time-series datapoints, each containing timestamp and statistics fields.
    """
    if statistics is None:
        statistics = ["Average"]

    if dimensions is None:
        dimensions = {}

    cw = boto3.client("cloudwatch", region_name=os.getenv("AWS_REGION"))

    metric_stat = {
        "Metric": {
            "Namespace": namespace,
            "MetricName": metric_name,
            "Dimensions": [{"Name": k, "Value": v} for k, v in dimensions.items()],
        },
        "Period": period,
        "Stat": statistics[0],
    }

    if unit:
        metric_stat["Unit"] = unit

    if len(statistics) > 1:
        metric_stat["Metrics"] = None

    metric_data_queries = [
        {
            "Id": "m1",
            "MetricStat": metric_stat,
            "ReturnData": True,
        }
    ]

    # CloudWatch GetMetricData supports one stat per MetricStat; to expose multiple
    # stats we query them separately and merge results.
    if len(statistics) > 1:
        metric_data_queries = []
        for idx, stat in enumerate(statistics, start=1):
            query = {
                "Id": f"m{idx}",
                "MetricStat": {
                    "Metric": {
                        "Namespace": namespace,
                        "MetricName": metric_name,
                        "Dimensions": [{"Name": k, "Value": v} for k, v in dimensions.items()],
                    },
                    "Period": period,
                    "Stat": stat,
                },
                "ReturnData": True,
            }
            if unit:
                query["MetricStat"]["Unit"] = unit
            metric_data_queries.append(query)

    try:
        response = cw.get_metric_data(
            MetricDataQueries=metric_data_queries,
            StartTime=start_time,
            EndTime=end_time,
            MaxDatapoints=max_datapoints,
            ScanBy=scan_by,
        )
    except (ClientError, BotoCoreError) as e:
        raise RuntimeError(f"CloudWatch get_metric_data failed: {e}") from e

    results: List[Dict[str, Any]] = []
    for series in response.get("MetricDataResults", []):
        label = series.get("Label")
        id_ = series.get("Id")
        timestamps = series.get("Timestamps", [])
        values = series.get("Values", [])
        status_code = series.get("StatusCode")

        for ts, value in zip(timestamps, values):
            results.append(
                {
                    "id": id_,
                    "label": label,
                    "timestamp": ts.isoformat() if hasattr(ts, "isoformat") else ts,
                    "value": value,
                    "status_code": status_code,
                    "messages": series.get("Messages", []),
                }
            )

    return results


def list_cloudwatch_metrics(
    namespace: Optional[str] = None,
    metric_name: Optional[str] = None,
    dimensions: Optional[Dict[str, str]] = None,
    recent_only: bool = False,
) -> List[Dict[str, Any]]:
    """
    List CloudWatch metrics optionally filtered by namespace, metric name, and dimensions.
    """
    if dimensions is None:
        dimensions = {}

    cw = boto3.client("cloudwatch", region_name=os.getenv("AWS_REGION"))

    kwargs: Dict[str, Any] = {}
    if namespace:
        kwargs["Namespace"] = namespace
    if metric_name:
        kwargs["MetricName"] = metric_name
    if dimensions:
        kwargs["Dimensions"] = [{"Name": k, "Value": v} for k, v in dimensions.items()]
    if recent_only:
        kwargs["RecentlyActive"] = "PT3H"

    metrics: List[Dict[str, Any]] = []
    paginator = cw.get_paginator("list_metrics")
    try:
        for page in paginator.paginate(**kwargs):
            for metric in page.get("Metrics", []):
                metrics.append(metric)
    except (ClientError, BotoCoreError) as e:
        raise RuntimeError(f"CloudWatch list_metrics failed: {e}") from e

    return metrics


def main() -> None:
    import argparse
    from datetime import datetime

    parser = argparse.ArgumentParser(description="Query Amazon CloudWatch metrics filtered by dimensions.")
    parser.add_argument("--namespace", required=True)
    parser.add_argument("--metric-name", required=True)
    parser.add_argument("--dimensions", default="{}", help='JSON object of dimensions, e.g. {"InstanceId":"i-123"}')
    parser.add_argument("--start-time", required=True, help="ISO8601 timestamp")
    parser.add_argument("--end-time", required=True, help="ISO8601 timestamp")
    parser.add_argument("--period", type=int, default=300)
    parser.add_argument("--statistics", default="Average", help='Comma-separated stats, e.g. "Average,Maximum"')
    parser.add_argument("--unit", default=None)
    parser.add_argument("--max-datapoints", type=int, default=1000)
    parser.add_argument("--scan-by", default="TimestampDescending")
    args = parser.parse_args()

    dimensions = json.loads(args.dimensions)
    statistics = [s.strip() for s in args.statistics.split(",") if s.strip()]

    def parse_time(value: str) -> datetime:
        return datetime.fromisoformat(value.replace("Z", "+00:00"))

    results = query_cloudwatch_metrics(
        namespace=args.namespace,
        metric_name=args.metric_name,
        dimensions=dimensions,
        start_time=parse_time(args.start_time),
        end_time=parse_time(args.end_time),
        period=args.period,
        statistics=statistics,
        unit=args.unit,
        max_datapoints=args.max_datapoints,
        scan_by=args.scan_by,
    )
    print(json.dumps(results, default=str))


if __name__ == "__main__":
    main()
